var fnRumbleJoystick func(joystick *Joystick, low_frequency_rumble uint16, high_frequency_rumble uint16, duration_ms uint32) bool

// Start a rumble effect.
//
// Each call to this function cancels any previous rumble effect, and calling
// it with 0 intensity stops any rumbling.
//
// This function requires you to process SDL events or call
// UpdateJoysticks() to update rumble state.
//
// Parameters:
//   - joystick: the joystick to vibrate.
//   - low_frequency_rumble: the intensity of the low frequency (left) rumble motor, from 0 to 0xFFFF.
//   - high_frequency_rumble: the intensity of the high frequency (right) rumble motor, from 0 to 0xFFFF.
//   - duration_ms: the duration of the rumble effect, in milliseconds.
//
// Returns: true, or false if rumble isn't supported on this joystick.
//
// Thread safety: It is safe to call this function from any thread.
//
// Since: SDL 3.2.0.
func RumbleJoystick(joystick *Joystick, low_frequency_rumble uint16, high_frequency_rumble uint16, duration_ms uint32) bool {
	return fnRumbleJoystick(joystick, low_frequency_rumble, high_frequency_rumble, duration_ms)
}

var fnRumbleJoystickTriggers func(joystick *Joystick, left_rumble uint16, right_rumble uint16, duration_ms uint32) bool

// Start a rumble effect in the joystick's triggers.
//
// Each call to this function cancels any previous trigger rumble effect, and
// calling it with 0 intensity stops any rumbling.
//
// Note that this is rumbling of the _triggers_ and not the game controller as
// a whole. This is currently only supported on Xbox One controllers. If you
// want the (more common) whole-controller rumble, use RumbleJoystick()
// instead.
//
// This function requires you to process SDL events or call
// UpdateJoysticks() to update rumble state.
//
// Parameters:
//   - joystick: the joystick to vibrate.
//   - left_rumble: the intensity of the left trigger rumble motor, from 0 to 0xFFFF.
//   - right_rumble: the intensity of the right trigger rumble motor, from 0 to 0xFFFF.
//   - duration_ms: the duration of the rumble effect, in milliseconds.
//
// Returns: true on success or false on failure; call GetError() for more information.
//
// Thread safety: It is safe to call this function from any thread.
//
// Since: SDL 3.2.0.
//
// See also: RumbleJoystick
func RumbleJoystickTriggers(joystick *Joystick, left_rumble uint16, right_rumble uint16, duration_ms uint32) bool {
	return fnRumbleJoystickTriggers(joystick, left_rumble, right_rumble, duration_ms)
}

